// backend/tests/integration/financial-hardening.test.ts
// Testes de Hardening Financeiro - FASE 9 ETAPA 1
// Invariantes do Ledger + Testes de Concorrência

import { describe, it, expect, beforeAll, afterAll } from '@jest/globals';
import { v4 as uuidv4 } from 'uuid';
import { pool } from '../../src/core/database/pool';
import { transactionService } from '../../src/core/economy/transactions/transaction.service';
import { accountService } from '../../src/core/economy/accounts/account.service';
import { bankP2PTransferService } from '../../src/core/unifybank/bank-p2p-transfer.service';
import { donationService } from '../../src/core/unifybank/donation.service';
// ⚠️ REMOVIDO: split-engine.service foi deprecado e removido do projeto
// TODO: Atualizar testes para usar @core/economy/split.service
import { regionalFundGovernanceService } from '../../src/core/unifybank/regional-fund-governance.service';
import { groupAccountService } from '../../src/core/economy/group-account.service';
import { resolveGlobalUserId } from '../../src/core/identity/identity.utils';

describe('FASE 9 - Hardening Financeiro - Etapa 1', () => {
  const testTenantId = uuidv4();
  let testUserId1: string;
  let testUserId2: string;
  let testGlobalUserId1: string;
  let testGlobalUserId2: string;
  let testAccountId1: string;
  let testAccountId2: string;
  let testGroupId: string;
  let testGroupAccountId: string;
  let testRegionId: string;

  beforeAll(async () => {
    // Criar tenant de teste
    await pool.query(
      `INSERT INTO tenants (tenant_id, name, city_id)
       VALUES ($1, 'Test Tenant Hardening', NULL)
       ON CONFLICT (tenant_id) DO NOTHING`,
      [testTenantId]
    );

    // Criar usuários de teste
    testUserId1 = uuidv4();
    testUserId2 = uuidv4();
    testGlobalUserId1 = uuidv4();
    testGlobalUserId2 = uuidv4();

    await pool.query(
      `INSERT INTO global_users (global_user_id, full_name, created_at)
       VALUES ($1, 'Test User 1', now()), ($2, 'Test User 2', now())
       ON CONFLICT (global_user_id) DO NOTHING`,
      [testGlobalUserId1, testGlobalUserId2]
    );

    await pool.query(
      `INSERT INTO users (user_id, tenant_id, email, global_user_id, created_at)
       VALUES ($1, $2, 'user1@test.com', $3, now()), ($4, $2, 'user2@test.com', $5, now())
       ON CONFLICT (user_id) DO NOTHING`,
      [testUserId1, testTenantId, testGlobalUserId1, testUserId2, testGlobalUserId2]
    );

    // Criar grupo de teste
    testGroupId = uuidv4();
    await pool.query(
      `INSERT INTO groups (group_id, tenant_id, owner_user_id, name, description, is_active, created_at)
       VALUES ($1, $2, $3, 'Test Group', 'Test Description', true, now())
       ON CONFLICT (group_id) DO NOTHING`,
      [testGroupId, testTenantId, testUserId1]
    );

    // Criar contas
    const account1 = await accountService.getOrCreateUserPrimaryAccount(
      testTenantId,
      testUserId1,
      'BRL'
    );
    testAccountId1 = account1.accountId;

    const account2 = await accountService.getOrCreateUserPrimaryAccount(
      testTenantId,
      testUserId2,
      'BRL'
    );
    testAccountId2 = account2.accountId;

    // Criar conta de grupo
    testGroupAccountId = await groupAccountService.createOrGetGroupAccount(
      testTenantId,
      testGroupId
    );

    // Criar transações para tornar usuários elegíveis
    await transactionService.transfer(testTenantId, {
      fromAccount: testAccountId1,
      toAccount: testAccountId2,
      amount: 10,
      eventId: uuidv4(),
      metadata: { type: 'test' },
    });

    // Definir regionId de teste
    testRegionId = 'test-region-id';
  });

  afterAll(async () => {
    // Limpar dados de teste
    try {
      await pool.query(`DELETE FROM regional_fund_votes WHERE proposal_id IN (SELECT proposal_id FROM regional_fund_proposals WHERE tenant_id = $1)`, [testTenantId]);
      await pool.query(`DELETE FROM regional_fund_proposals WHERE tenant_id = $1`, [testTenantId]);
      await pool.query(`DELETE FROM transactions WHERE tenant_id = $1`, [testTenantId]);
      await pool.query(`DELETE FROM ledger WHERE tenant_id = $1`, [testTenantId]);
      await pool.query(`DELETE FROM accounts WHERE tenant_id = $1`, [testTenantId]);
      await pool.query(`DELETE FROM groups WHERE tenant_id = $1`, [testTenantId]);
      await pool.query(`DELETE FROM users WHERE tenant_id = $1`, [testTenantId]);
      await pool.query(`DELETE FROM tenants WHERE tenant_id = $1`, [testTenantId]);
    } catch (error) {
      // Ignorar erros de limpeza
    }
  });

  describe('INVARIANTE 1 - Double-Entry Balanceado', () => {
    it('deve garantir que sum(debits) === sum(credits) para cada transação', async () => {
      // Criar transação
      const eventId = uuidv4();
      const result = await transactionService.transfer(testTenantId, {
        fromAccount: testAccountId1,
        toAccount: testAccountId2,
        amount: 25,
        eventId,
        metadata: { type: 'test' },
      });

      // Verificar ledger balanceado
      const ledgerCheck = await pool.query<{ total_debits: string; total_credits: string }>(
        `
        SELECT 
          COALESCE(SUM(CASE WHEN entry_type = 'debit' THEN amount ELSE 0 END), 0)::text as total_debits,
          COALESCE(SUM(CASE WHEN entry_type = 'credit' THEN amount ELSE 0 END), 0)::text as total_credits
        FROM ledger
        WHERE transaction_id = $1
        `,
        [result.transaction.transactionId]
      );

      const totalDebits = parseFloat(ledgerCheck.rows[0]?.total_debits || '0');
      const totalCredits = parseFloat(ledgerCheck.rows[0]?.total_credits || '0');

      expect(Math.abs(totalDebits - totalCredits)).toBeLessThan(0.01);
    });
  });

  describe('INVARIANTE 2 - Saldo Não-Negativo', () => {
    it('deve bloquear transferência que deixaria saldo negativo em conta de usuário', async () => {
      // Adicionar saldo inicial
      await pool.query(
        `UPDATE accounts SET balance = 50 WHERE account_id = $1`,
        [testAccountId1]
      );

      // Tentar transferir mais do que tem
      await expect(
        transactionService.transfer(testTenantId, {
          fromAccount: testAccountId1,
          toAccount: testAccountId2,
          amount: 100, // Mais do que o saldo
          eventId: uuidv4(),
          metadata: { type: 'test' },
        })
      ).rejects.toThrow('Non-negative balance invariant violated');

      // Verificar que nenhuma transação foi criada
      const transactions = await pool.query<{ count: string }>(
        `
        SELECT COUNT(*)::text as count
        FROM transactions
        WHERE tenant_id = $1
          AND from_account = $2
          AND amount = 100
        `,
        [testTenantId, testAccountId1]
      );

      expect(parseInt(transactions.rows[0]?.count || '0', 10)).toBe(0);
    });
  });

  describe('INVARIANTE 3 - Idempotência Absoluta', () => {
    it('deve rejeitar mesmo eventId com payload diferente', async () => {
      const eventId = uuidv4();

      // Primeira transferência
      await transactionService.transfer(testTenantId, {
        fromAccount: testAccountId1,
        toAccount: testAccountId2,
        amount: 10,
        eventId,
        metadata: { type: 'test' },
      });

      // Tentar usar mesmo eventId com payload diferente
      await expect(
        transactionService.transfer(testTenantId, {
          fromAccount: testAccountId1,
          toAccount: testAccountId2,
          amount: 20, // Amount diferente
          eventId, // Mesmo eventId
          metadata: { type: 'test' },
        })
      ).rejects.toThrow('Idempotency violation');
    });
  });

  describe.skip('INVARIANTE 4 - Split Invariants (DEPRECADO - aguardando migração para @core/economy/split.service)', () => {
    it('deve garantir que soma dos valores dos splits = valor base', async () => {
      // Criar transação base
      const baseEventId = uuidv4();
      const baseAmount = 100;
      
      const baseResult = await transactionService.transfer(testTenantId, {
        fromAccount: testAccountId1,
        toAccount: testGroupAccountId,
        amount: baseAmount,
        eventId: baseEventId,
        metadata: { type: 'test' },
      });

      // Aplicar split
      const splitResult = await splitEngineService.applySplit({
        tenantId: testTenantId,
        baseTransactionId: baseResult.transaction.transactionId,
        amount: baseAmount,
        context: 'donation',
        metadata: {
          targetId: testGroupId,
          globalUserId: testGlobalUserId1,
        },
      });

      // Verificar que soma dos splits = base
      const totalSplitAmount = splitResult.entries.reduce((sum, entry) => sum + entry.amount, 0);
      expect(Math.abs(totalSplitAmount - baseAmount)).toBeLessThan(0.01);
    });
  });

  describe('TESTE 1 - P2P Concorrente', () => {
    it('deve criar apenas 1 transação quando 50 chamadas simultâneas usam mesmo eventId', async () => {
      const eventId = uuidv4();

      // Adicionar saldo suficiente
      await pool.query(
        `UPDATE accounts SET balance = 1000 WHERE account_id = $1`,
        [testAccountId1]
      );

      // 50 chamadas simultâneas
      const promises = Array.from({ length: 50 }, () =>
        transactionService.transfer(testTenantId, {
          fromAccount: testAccountId1,
          toAccount: testAccountId2,
          amount: 5,
          eventId, // Mesmo eventId
          metadata: { type: 'test' },
        })
      );

      const results = await Promise.all(promises);

      // Todas devem retornar a mesma transactionId
      const transactionIds = new Set(results.map((r) => r.transaction.transactionId));
      expect(transactionIds.size).toBe(1);

      // Verificar que apenas 1 transação foi criada
      const transactions = await pool.query<{ count: string }>(
        `
        SELECT COUNT(*)::text as count
        FROM transactions
        WHERE event_id = $1
        `,
        [eventId]
      );

      expect(parseInt(transactions.rows[0]?.count || '0', 10)).toBe(1);

      // Verificar ledger balanceado
      const ledgerCheck = await pool.query<{ total_debits: string; total_credits: string }>(
        `
        SELECT 
          COALESCE(SUM(CASE WHEN entry_type = 'debit' THEN amount ELSE 0 END), 0)::text as total_debits,
          COALESCE(SUM(CASE WHEN entry_type = 'credit' THEN amount ELSE 0 END), 0)::text as total_credits
        FROM ledger
        WHERE transaction_id = $1
        `,
        [Array.from(transactionIds)[0]]
      );

      const totalDebits = parseFloat(ledgerCheck.rows[0]?.total_debits || '0');
      const totalCredits = parseFloat(ledgerCheck.rows[0]?.total_credits || '0');
      expect(Math.abs(totalDebits - totalCredits)).toBeLessThan(0.01);
    });
  });

  describe('TESTE 2 - Doação Concorrente', () => {
    it('deve criar apenas 1 transação base e 1 grupo de splits quando 50 chamadas simultâneas usam mesmo eventId', async () => {
      const eventId = uuidv4();

      // Adicionar saldo suficiente
      await pool.query(
        `UPDATE accounts SET balance = 1000 WHERE account_id = $1`,
        [testAccountId1]
      );

      // 50 chamadas simultâneas
      const promises = Array.from({ length: 50 }, () =>
        donationService.createDonation(testTenantId, {
          fromUserId: testUserId1,
          targetType: 'group',
          targetId: testGroupId,
          amount: 10,
          eventId, // Mesmo eventId
        })
      );

      const results = await Promise.all(promises);

      // Todas devem retornar a mesma transactionId
      const transactionIds = new Set(results.map((r) => r.transactionId));
      expect(transactionIds.size).toBe(1);

      // Verificar que apenas 1 transação base foi criada
      const baseTransactions = await pool.query<{ count: string }>(
        `
        SELECT COUNT(*)::text as count
        FROM transactions
        WHERE event_id = $1
        `,
        [eventId]
      );

      expect(parseInt(baseTransactions.rows[0]?.count || '0', 10)).toBe(1);

      // Verificar splits (deve ter apenas 1 grupo de splits)
      const splitGroupIds = await pool.query<{ split_group_id: string }>(
        `
        SELECT DISTINCT metadata->>'splitGroupId' as split_group_id
        FROM transactions
        WHERE tenant_id = $1
          AND metadata->>'type' = 'split'
          AND metadata->>'originTransactionId' = $2
        `,
        [testTenantId, Array.from(transactionIds)[0]]
      );

      expect(splitGroupIds.rows.length).toBeGreaterThan(0);
      const uniqueSplitGroups = new Set(splitGroupIds.rows.map((r) => r.split_group_id));
      expect(uniqueSplitGroups.size).toBe(1);
    });
  });

  describe.skip('TESTE 3 - Split Atomicidade (DEPRECADO - aguardando migração para @core/economy/split.service)', () => {
    it('deve fazer rollback total se um split falhar (0 splits criados)', async () => {
      // Criar transação base
      const baseEventId = uuidv4();
      const baseResult = await transactionService.transfer(testTenantId, {
        fromAccount: testAccountId1,
        toAccount: testGroupAccountId,
        amount: 50,
        eventId: baseEventId,
        metadata: { type: 'test' },
      });

      // Tentar aplicar split com targetId inválido (vai falhar)
      await expect(
        splitEngineService.applySplit({
          tenantId: testTenantId,
          baseTransactionId: baseResult.transaction.transactionId,
          amount: 50,
          context: 'donation',
          metadata: {
            targetId: 'invalid-group-id', // Grupo não existe
            globalUserId: testGlobalUserId1,
          },
        })
      ).rejects.toThrow();

      // Verificar que nenhum split foi criado
      const splits = await pool.query<{ count: string }>(
        `
        SELECT COUNT(*)::text as count
        FROM transactions
        WHERE tenant_id = $1
          AND metadata->>'type' = 'split'
          AND metadata->>'originTransactionId' = $2
        `,
        [testTenantId, baseResult.transaction.transactionId]
      );

      expect(parseInt(splits.rows[0]?.count || '0', 10)).toBe(0);
    });
  });

  describe('TESTE 4 - Governança Execute Concorrente', () => {
    it('deve criar apenas 1 execução quando 2 chamadas simultâneas executam mesma proposta', async () => {
      // Criar proposta aprovada
      const votingStartsAt = new Date();
      votingStartsAt.setMinutes(votingStartsAt.getMinutes() - 10);
      const votingEndsAt = new Date();
      votingEndsAt.setMinutes(votingEndsAt.getMinutes() + 10);

      const proposal = await regionalFundGovernanceService.createProposal(
        testTenantId,
        testGlobalUserId1,
        {
          title: 'Concurrent Execute Test',
          description: 'Test Description',
          proposalType: 'PROJECT_FUNDING',
          targetType: 'group',
          targetId: testGroupId,
          amount: 40,
          votingStartsAt,
          votingEndsAt,
        }
      );

      await regionalFundGovernanceService.openVoting(testTenantId, proposal.proposalId);
      await regionalFundGovernanceService.vote(
        testTenantId,
        proposal.proposalId,
        testGlobalUserId1,
        'YES'
      );
      await regionalFundGovernanceService.vote(
        testTenantId,
        proposal.proposalId,
        testGlobalUserId2,
        'YES'
      );
      await regionalFundGovernanceService.closeVoting(testTenantId, proposal.proposalId);

      // Criar saldo no fundo regional
      const regionAccountId = await accountService.getAccountsByOwner(
        testTenantId,
        testRegionId,
        'group'
      );
      let finalRegionAccountId: string;
      if (regionAccountId.length > 0) {
        finalRegionAccountId = regionAccountId[0].accountId;
      } else {
        const created = await accountService.createAccount(testTenantId, {
          ownerId: testRegionId,
          ownerType: 'group',
          currency: 'BRL',
        });
        finalRegionAccountId = created.accountId;
      }

      await pool.query(
        `UPDATE accounts SET balance = balance + 100 WHERE account_id = $1`,
        [finalRegionAccountId]
      );

      // 2 chamadas simultâneas
      const [result1, result2] = await Promise.all([
        regionalFundGovernanceService.executeProposal(testTenantId, proposal.proposalId),
        regionalFundGovernanceService.executeProposal(testTenantId, proposal.proposalId),
      ]);

      // Ambas devem retornar a mesma transactionId
      expect(result1.transactionId).toBe(result2.transactionId);

      // Verificar que apenas 1 transação de execução foi criada
      const executions = await pool.query<{ count: string }>(
        `
        SELECT COUNT(*)::text as count
        FROM transactions
        WHERE metadata->>'proposalId' = $1
          AND metadata->>'type' = 'governance_execution'
        `,
        [proposal.proposalId]
      );

      expect(parseInt(executions.rows[0]?.count || '0', 10)).toBe(1);

      // Verificar que proposta está EXECUTED
      const proposalFinal = await pool.query<{
        status: string;
        execution_transaction_id: string | null;
      }>(
        `
        SELECT status, execution_transaction_id
        FROM regional_fund_proposals
        WHERE proposal_id = $1
        LIMIT 1
        `,
        [proposal.proposalId]
      );

      expect(proposalFinal.rows[0]?.status).toBe('EXECUTED');
      expect(proposalFinal.rows[0]?.execution_transaction_id).toBe(result1.transactionId);
    });
  });

  describe('REGRA GLOBAL - Zero Fallback Silencioso', () => {
    it('deve lançar erro explícito se região não encontrada em produção', async () => {
      // Salvar NODE_ENV original
      const originalEnv = process.env.NODE_ENV;
      process.env.NODE_ENV = 'production';

      try {
        // Criar tenant sem cityId
        const tenantWithoutCity = uuidv4();
        await pool.query(
          `INSERT INTO tenants (tenant_id, name, city_id)
           VALUES ($1, 'Test Tenant No City', NULL)
           ON CONFLICT (tenant_id) DO NOTHING`,
          [tenantWithoutCity]
        );

        // Tentar resolver região (deve falhar)
        const { regionAccountService } = await import('@core/economy/region-account.service');
        await expect(
          regionAccountService.resolveRegionAccountId({
            tenantId: tenantWithoutCity,
          })
        ).rejects.toThrow('Region not found');

        // Limpar
        await pool.query(`DELETE FROM tenants WHERE tenant_id = $1`, [tenantWithoutCity]);
      } finally {
        // Restaurar NODE_ENV
        if (originalEnv) {
          process.env.NODE_ENV = originalEnv;
        } else {
          delete process.env.NODE_ENV;
        }
      }
    });
  });
});




























